            self.cur=('door', a.get('href'), [])
        if tag=='a' and 'entry-list__title' in cls.split():
            self.cur=('entry', a.get('href'), [])
        if tag=='span' and 'entry-list__title' in cls.split():
            href=None
            for t,c,aa in reversed(self.stack):
                if t=='a':
                    href=aa.get('href'); break
            self.cur=('entry', href, [])
        if tag=='h1':
            self.cur=('h1', a.get('class',''), [])
        if tag=='h2':
            self.cur=('h2', a.get('class',''), [])
        if tag=='h3':
