        if tag=='a' and self.stack and any(t=='h3' for t,_,_ in self.stack[-3:]):
            self.cur=('h3a', a.get('href'), [])
    def handle_data(self, data):
        if not self.cur: return
        self.cur[-1].append(data)
    def handle_endtag(self, tag):
        if self.cur:
            kind=self.cur[0]
            text=''.join(self.cur[-1]).strip()
            if kind=='hero' and tag=='h1':
                self.hero=text; self.cur=None
            elif kind=='door' and tag=='a':
                self.doors.append((self.cur[1], text)); self.cur=None
            elif kind=='entry' and tag in ('a','span'):
                self.entries.append((self.cur[1], text)); self.cur=None
            elif kind=='h1' and tag=='h1':
                self.heads.append(('h1', self.cur[1], text)); self.cur=None
            elif kind=='h2' and tag=='h2':
                self.heads.append(('h2', self.cur[1], text)); self.cur=None
            elif kind=='h3a' and tag=='a':
                self.domain_links.append((self.cur[1], text)); self.cur=None
            elif kind=='h3' and tag=='h3':
                self.cur=None
        if self.stack: self.stack.pop()

